package mediatoolsite

func ourbits() Template {
	t := basic("ourbits", "OURBITS", "https://ourbits.club")
	t.Definition["schema"] = "NexusPHP"
	t.Definition["encoding"] = "UTF-8"
	t.Definition["additional_domain"] = []any{"https://pt.ourhelp.club"}
	t.Definition["meta"] = Map{"has_hr": true}
	t.Definition["requests"].(Map)["search"] = Map{"parser": "CssSelector", "method": "GET", "path": "/torrents.php", "params": Map{"search": []any{"{keyword}"}}, "list": Map{"selector": "table.torrents tr:has(table.torrentname)", "container": "table.torrents", "next_page": Map{"selector": "a[rel='next'][href], a[href]:contains('下一页'), a[href]:contains('下一頁'), a[href]:contains('Next'), a[href]:contains('next')", "attribute": "href"}}, "fields": Map{"id": Map{"selector": "a[href*='details.php?id=']", "attribute": "href", "filters": []any{Map{"name": "re_search", "args": []any{"\\d+", 0}}}}, "title": Map{"any": []any{Map{"selector": "a[title][href*='details.php?id=']", "attribute": "title"}, Map{"selector": "a[href*='details.php?id=']"}}}, "details": Map{"selector": "a[href*='details.php?id=']", "attribute": "href"}, "download": Map{"selector": "a[href*='download.php?id=']", "attribute": "href"}, "size": Map{"selector": "td.rowfollow:nth-child(5)", "filters": []any{Map{"name": "byte_size"}}}, "seeders": Map{"selector": "td:nth-child(6):not(.embedded)"}, "leechers": Map{"selector": "td:nth-child(7):not(.embedded)"}, "downloadvolumefactor": Map{"any": []any{Map{"selector": "img.pro_free,img.pro_free2up", "attribute": "class", "filters": []any{Map{"name": "not_blank", "args": []any{0, ""}}}}, Map{"selector": "img.pro_50pctdown,img.pro_50pctdown2up", "attribute": "class", "filters": []any{Map{"name": "not_blank", "args": []any{0.5, ""}}}}, Map{"selector": "img.pro_30pctdown", "attribute": "class", "filters": []any{Map{"name": "not_blank", "args": []any{0.3, ""}}}}}}, "description": Map{"selector": "table.torrentname tr > td.embedded", "remove": "div,a,img,b", "filters": []any{Map{"name": "replace", "args": []any{"剩余时间：", ""}}}}, "labels": Map{"selector": "table.torrentname tr > td.embedded > div > a[href*='?tags[]='] > span", "array": true}, "hr": Map{"selector": "img.hitandrun", "attribute": "class", "filters": []any{Map{"name": "not_blank", "args": []any{true, ""}}}}}}
	return t
}
